style.css:
/* Keyframes สำหรับสีตัวอักษร */
@keyframes redBlackSmooth {
    0%   { color: red; }
    50%  { color: black; }
    100% { color: red; }
}

/* ใช้กับทุกตัวอักษรบนเว็บ Roblox */
body, body * {
    animation: redBlackSmooth 3s infinite ease-in-out; /* เพิ่มเวลาและ easing ให้ลื่น */
    transition: color 1.5s ease-in-out;               /* ทำให้การเปลี่ยนสีลื่นมากขึ้น */
}
